package com.lexorion.workforce.api;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.ConstraintViolationException;import java.time.Instant;import java.util.Map;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(WorkforceException.class)ResponseEntity<?> workforce(WorkforceException e,HttpServletRequest r){return ResponseEntity.status(e.status()).body(Map.of("timestamp",Instant.now(),"status",e.status(),"message",e.getMessage(),"path",r.getRequestURI()));}@ExceptionHandler({MethodArgumentNotValidException.class,ConstraintViolationException.class,MethodArgumentTypeMismatchException.class})ResponseEntity<?> validation(Exception e,HttpServletRequest r){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"message","Validation failed","path",r.getRequestURI()));}}
